import {createWorld} from './world3d.js';
let world=null;let illustrated=true,paintArea='room';
import {chapters,initial,act} from './engine.js';
import {itemArt} from './items.js';
const $=s=>document.querySelector(s);let state=initial(),name='Traveller',zoom=1,audio=false,ctx=null,reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,hintTimer;
const show=id=>{if(!$('#'+id).open)$('#'+id).showModal();};const close=id=>$('#'+id).close();
function tell(text,error=false){$('#message').textContent=text;$('#message').classList.toggle('error',error);}
function chime(){if(!audio)return;try{ctx||=new (window.AudioContext||window.webkitAudioContext)();ctx.resume();const o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.setValueAtTime(660,ctx.currentTime);o.frequency.exponentialRampToValueAtTime(990,ctx.currentTime+.1);g.gain.setValueAtTime(.035,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.2);o.connect(g);g.connect(ctx.destination);o.start();o.stop(ctx.currentTime+.21);}catch{}}
function dispatch(event,success){try{state=act(state,event);render();if(success)tell(success);chime();return true;}catch(e){tell(e.message,true);return false;}}
function speak(who,text,buttons=[['Back to the room',()=>close('conversation')]]){const portraits={ghost:100,scrooge:0,person:[25,50,75][state.level]},q=chapters[state.level];$('#speakerPortrait').style.backgroundPosition=(portraits[who]??50)+'% 50%';$('#speakerName').textContent=who==='ghost'?'The Spirit of Christmas Past':who==='scrooge'?'Ebenezer Scrooge':q.person;$('#speakerRole').textContent=who==='ghost'?'A SECOND CHANCE':who==='scrooge'?'A HEART LEARNING TO OPEN':q.fullName;$('#speech').textContent=text;$('#dialogueActions').replaceChildren();for(const [label,fn] of buttons){const b=document.createElement('button');b.textContent=label;b.onclick=fn;$('#dialogueActions').append(b);}show('conversation');}
function talk(){const q=chapters[state.level];if(state.selected){if(dispatch({type:'use',target:'person'},q.person+' receives the '+(q.use==='invitation'?'invitation':'letter')+'. Continue the memory to see what changes.'))speak('person','You found it. Thank you for noticing. A small thing can mean more than you know.');return;}const helped=state.core.flags.includes(q.core);dispatch({type:'talk'});speak('person',helped?'You have already changed this memory. Let the clock continue and see where kindness takes us.':q.line,[[helped?'Let’s see what happens':q.reply,()=>close('conversation')]]);}
function render(){world?.sync(state);paintState();const q=chapters[state.level];$('#memoryTitle').textContent=q.title;$('#mission').textContent=q.need;$('#story').textContent=q.intro;$('#memoryNumber').textContent=String(state.level+1).padStart(2,'0');$('#personName').textContent=q.person;$('#person').style.setProperty('--portrait-position',[25,50,75][state.level]+'%');$('#person').setAttribute('aria-label','Speak to '+q.person);$('#person').classList.toggle('helped',state.core.flags.includes(q.core)||state.core.solved);$('#points').textContent=state.done.length*100;$('#gifts').textContent=state.done.length+' / 3';$('#progress').setAttribute('aria-valuenow',state.done.length);$('#progress i').style.width=state.done.length/3*100+'%';$('#discoveries').textContent=state.found.length+' / '+q.items.length;$('#explorer').textContent=name;$('#artboard').classList.toggle('before',state.core.time===0);$('#artboard').classList.toggle('restored',state.core.solved);$('#restored').hidden=!state.core.solved;$('#timeState').innerHTML='<i></i>'+ (state.core.solved?'A KINDER OUTCOME':state.core.time===0?'BEFORE THE MOMENT · TIME PAUSED':'THE MOMENT HAS PASSED');$('#continue').textContent=state.core.solved?'Collect kindness ✓':'Continue ▷';$('#rewind').disabled=state.core.solved;$('#mobileRewind').disabled=state.core.solved;$('#mobileContinue').textContent=state.core.solved?'Collect kindness ✓':'Continue ▷';$('#window').hidden=state.level!==1;$('#trackSwitch').classList.toggle('ready',state.selected==='handle');$('#cart').classList.toggle('ready',state.selected==='ribbon');$('#trackSwitch').hidden=$('#cart').hidden=state.level!==2;
 const steps=state.level===0?[['Speak with Nujhat',state.talked],['Rewind the missed moment',state.core.rewound],['Find the sealed invitation',state.found.includes('invitation')],['Give the invitation to Nujhat',state.core.flags.includes('invite')],['Continue the memory',state.core.solved]]:state.level===1?[['Speak with Hafsa',state.talked],['Rewind and close the window',state.core.flags.includes('window')],['Find the thank-you letter',state.found.includes('letter')],['Return the letter to Hafsa',state.core.flags.includes('deliver')],['Continue the memory',state.core.solved]]:[['Speak with Foysal',state.talked],['Rewind before the cart falls',state.core.rewound],['Find a handle and a ribbon',q.required.every(i=>state.found.includes(i))],['Use the handle on the track',state.core.flags.includes('switch')],['Use the ribbon on the cart',state.core.flags.includes('secure')],['Continue the memory',state.core.solved]];
 $('#objectives').replaceChildren();steps.forEach(([label,done])=>{const li=document.createElement('li');li.classList.toggle('done',done);const mark=document.createElement('span');mark.textContent=done?'✓':' ';li.append(mark,document.createTextNode(label));$('#objectives').append(li);});
 $('#objects').replaceChildren();q.items.filter(i=>!state.found.includes(i.id)).forEach(i=>{if(q.required.includes(i.id)&&(!state.core.rewound||state.core.time!==0))return;const b=document.createElement('button');b.className='hidden-item '+(q.required.includes(i.id)?'':'optional');b.dataset.item=i.id;b.dataset.tip=i.name;b.style.left=i.x+'%';b.style.top=i.y+'%';b.setAttribute('aria-label','Inspect '+i.name);b.innerHTML=itemArt(i.kind);b.onclick=()=>find(i.id);$('#objects').append(b);});
 $('#inventory').replaceChildren();state.bag.forEach(id=>{const i=q.items.find(i=>i.id===id),b=document.createElement('button');b.className='inventory-slot'+(state.selected===id?' selected':'');b.dataset.bag=id;b.setAttribute('aria-label','Select '+i.name);b.setAttribute('aria-pressed',state.selected===id?'true':'false');b.innerHTML=itemArt(i.kind);const label=document.createElement('span');label.textContent=i.name;b.append(label);b.onclick=()=>{dispatch({type:'select',id});tell(state.selected?i.name+' selected. Tap the person or object it could help.':'Item put away.');};$('#inventory').append(b);});for(let i=state.bag.length;i<5;i++){const slot=document.createElement('div');slot.className='inventory-slot empty';slot.setAttribute('aria-hidden','true');$('#inventory').append(slot);}
 $('#bagHelp').textContent=state.selected?'Item selected · tap its destination in the room.':'Find an object. Select it. Use it in the scene.';
 $('#searchList').replaceChildren();for(const i of q.items.filter(i=>!state.found.includes(i.id))){const b=document.createElement('button');b.textContent='Inspect '+i.name;b.onclick=()=>find(i.id);$('#searchList').append(b);}for(const [label,fn] of [['Talk to '+q.person,talk],...(state.level===1?[['Inspect / close window',()=>dispatch({type:'window'},'The draft is stopped. The letter can be recovered.')]]:[]),...(state.level===2?[['Use item on track switch',()=>use('switch')],['Use item on toy cart',()=>use('cart')]]:[])]){const b=document.createElement('button');b.textContent=label;b.onclick=fn;$('#searchList').append(b);}}
function find(id){const item=chapters[state.level].items.find(i=>i.id===id);if(dispatch({type:'find',id},item.name+' collected.'+(chapters[state.level].required.includes(id)?' It may help someone.':' A lovely curiosity for your collection. No extra points needed.')))$('#bagHelp').textContent='Select a collected item to use it in the room.';}
function use(target){dispatch({type:'use',target},target==='switch'?'The cart is on the safe route. Now secure the toy with a ribbon.':'The reindeer is secured. Continue the memory to see the gentler ending.');}
function reward(){const q=chapters[state.level];$('#rewardTitle').textContent=['A place at the table.','Words that warm a heart.','A keepsake, safe at last.'][state.level];$('#rewardStory').textContent=q.success;$('#commitText').textContent='I commit to this kindness: '+q.deed;$('#commit').checked=false;$('#collect').disabled=true;show('reward');}
function focusView(view){world?.travel(view);paintArea=view;paintState(); const v=$('#viewport'),a=$('#artboard');zoom=view==='room'?1:1.45;a.style.width=zoom*100+'%';$('#zoomLabel').textContent=Math.round(zoom*100)+'%';const coords={room:[.5,.5],desk:[.24,.64],hearth:[.84,.49],toys:[.64,.76],courtyard:[.5,.5]}[view];requestAnimationFrame(()=>v.scrollTo({left:coords[0]*a.clientWidth-v.clientWidth/2,top:coords[1]*a.clientHeight-v.clientHeight/2,behavior:reduced?'instant':'smooth'}));document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('selected',b.dataset.view===view));}
$('#enterForm').onsubmit=e=>{e.preventDefault();name=$('#name').value.trim()||'Traveller';close('welcome');$('#game').focus({preventScroll:true});render();$('#searchList').hidden=false;tell('Welcome, '+name+'. Speak with Nujhat, then search the room.');};$('#person').onclick=talk;$('#rewind').onclick=()=>dispatch({type:'time',action:'rewind'},'The clock turns back. The lost objects can be found again.');$('#continue').onclick=()=>{if(state.core.solved)return reward();if(dispatch({type:'time',action:'resume'})){tell(state.core.solved?chapters[state.level].success+' Select “Collect kindness” to carry it with you.':'The moment passes unchanged. Rewind and finish helping '+chapters[state.level].person+'.');}};$('#window').onclick=()=>dispatch({type:'window'},'You close the window. The letter is safe from the draft.');$('#trackSwitch').onclick=()=>use('switch');$('#cart').onclick=()=>use('cart');$('#ghost').onclick=()=>{const q=chapters[state.level];speak('ghost',q.hint,[['Show me a gentle clue',()=>{close('conversation');if(!state.talked){focusView('hearth');$('#person').classList.add('hint');}else if(state.core.time!==0){$('#rewind').focus();tell('Use the gift of time: rewind this memory first.');}else{let target;if(state.level===1&&!state.core.flags.includes('window'))target=$('#window');else{const missing=q.items.find(i=>q.required.includes(i.id)&&!state.found.includes(i.id));target=missing?document.querySelector('[data-item="'+missing.id+'"]'):state.level<2?$('#person'):!state.core.flags.includes('switch')?$('#trackSwitch'):$('#cart');}if(target){target.classList.add('hint');target.scrollIntoView({block:'center',inline:'center',behavior:reduced?'instant':'smooth'});}}clearTimeout(hintTimer);hintTimer=setTimeout(()=>document.querySelectorAll('.hint').forEach(e=>e.classList.remove('hint')),4500);}]]);};$('#commit').onchange=()=>$('#collect').disabled=!$('#commit').checked;$('#collect').onclick=()=>{if(!dispatch({type:'collect',commit:$('#commit').checked}))return;close('reward');if(state.level<2){speak('scrooge','I had forgotten how much a small kindness could mean. There is another memory waiting for us.',[['Explore the next memory',()=>{close('conversation');dispatch({type:'next'});focusView('room');tell(chapters[state.level].intro);}]]);}else{$('#endingMessage').textContent=name+', you found what was lost and restored three memories. Your little kindness made a mighty difference.';show('ending');}};
$('#mobileRewind').onclick=()=>$('#rewind').click();$('#mobileContinue').onclick=()=>$('#continue').click();$('#mobileJournal').onclick=()=>$('.journal').scrollIntoView({behavior:reduced?'instant':'smooth'});$('#settings').onclick=()=>show('helpDialog');$('#pitch').onclick=$('#endingPitch').onclick=()=>show('pitchDialog');$('#accessibleSearch').onclick=()=>{const open=$('#searchList').hidden;$('#searchList').hidden=!open;$('#accessibleSearch').setAttribute('aria-expanded',open?'true':'false');};document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>close(b.dataset.close));document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>focusView(b.dataset.view));for(const [id,delta] of [['zoomIn',.25],['zoomOut',-.25]])$('#'+id).onclick=()=>{world?.zoom(delta);zoom=Math.max(1,Math.min(2,zoom+delta));$('#artboard').style.width=zoom*100+'%';$('#zoomLabel').textContent=Math.round(zoom*100)+'%';};function motion(){world?.motion(!reduced);document.body.classList.toggle('reduced-motion',reduced);$('#motion').textContent='Subtle motion: '+(reduced?'off':'on');}$('#motion').onclick=()=>{reduced=!reduced;motion();};$('#sound').onclick=()=>{audio=!audio;$('#sound').textContent=audio?'Sound on':'Sound off';$('#sound').setAttribute('aria-pressed',audio?'true':'false');chime();};$('#resetAttempt').onclick=()=>{close('helpDialog');if(state.committed){tell('This kindness is already collected. Continue to the next memory.');return;}dispatch({type:'reset'},'This unfinished scene is reset. Your earned kindness is unchanged.');};$('#newGame').onclick=()=>{close('helpDialog');show('resetConfirm');};function restart(){document.querySelectorAll('dialog[open]').forEach(d=>d.close());state=initial();name='Traveller';$('#name').value='';zoom=1;$('#artboard').style.width='100%';$('#zoomLabel').textContent='100%';render();focusView('room');show('welcome');}$('#confirmNew').onclick=$('#replay').onclick=restart;render();motion();show('welcome');

function nextStep(){const q=chapters[state.level];if(!state.talked){world?.guide('person');if(illustrated)focusView('hearth');tell('Meet '+q.person+'. Tap the character, or use “Talk” in the journal.');return;}if(state.core.solved){reward();return;}if(state.core.time!==0){$('#rewind').click();tell('The room is restored to before the loss. Now find what can help.');return;}let target;if(state.level===1&&!state.core.flags.includes('window'))target='window';else{const missing=q.items.find(i=>q.required.includes(i.id)&&!state.found.includes(i.id));target=missing?.id||(state.level<2?'person':!state.core.flags.includes('switch')?'switch':!state.core.flags.includes('secure')?'cart':'continue');}if(target==='continue'){ $('#continue').click();return;}world?.guide(target);if(illustrated){focusView(target==='person'?'hearth':target==='window'?'desk':state.level===2?'toys':'desk');const node=target==='person'?$('#person'):target==='window'?$('#window'):target==='switch'?$('#trackSwitch'):target==='cart'?$('#cart'):document.querySelector('[data-item="'+target+'"]');node?.classList.add('hint');setTimeout(()=>node?.classList.remove('hint'),3000);}tell(target==='person'?'Select the letter in your satchel, then give it to '+q.person+'.':'A closer look: '+target+'. Tap it to inspect. The journal list is always available too.');}
$('#guide3d').onclick=nextStep;$('#openMap').onclick=()=>show('mapDialog');document.querySelectorAll('[data-area]').forEach(b=>b.onclick=()=>{focusView(b.dataset.area);close('mapDialog');tell('Exploring '+b.querySelector('strong').textContent+'. Drag the scene gently to look around.');});
try{world=createWorld($('#worldView'),id=>{if(id==='person')talk();else if(id==='window')$('#window').click();else if(id==='switch')use('switch');else if(id==='cart')use('cart');else find(id);});world.sync(state);world.motion(!reduced);window.__worldReady=true;}catch(e){$('#worldView').innerHTML='<p class="fallback3d">3D could not start on this device. Use the illustrated scene and the journal’s object list to play every quest.</p>';document.body.classList.add('fallback-mode');$('#searchList').hidden=false;window.__worldReady=false;}

function paintState(){if(!$('#paintedRoom'))return;const outside=paintArea==='courtyard';const path=new URL(outside?'./assets/courtyard.webp':'./assets/workshop.webp',import.meta.url).href;if($('#paintedRoom').src!==path)$('#paintedRoom').src=path;$('#artboard').classList.toggle('outside',outside);document.body.classList.toggle('memory-warm',state.core.solved);document.body.classList.toggle('memory-before',state.core.time===0);document.body.classList.toggle('memory-missed',state.core.time===100&&!state.core.solved);}
$('#skinToggle').onclick=()=>{illustrated=!illustrated;document.body.classList.toggle('illustrated-mode',illustrated);$('#skinToggle').textContent=illustrated?'View in 3D':'Illustrated view';$('#skinToggle').setAttribute('aria-pressed',illustrated?'false':'true');world?.active?.(!illustrated);if(illustrated)focusView(paintArea);};world?.active?.(false);paintState();
